\title{A Group-Theoretic Structure Theory of Reversible Binary Cellular Automata on Cyclic Lattices}
\author{Aristotle}
\date{July 10, 2026}

\begin{document}

\begin{abstract}
We study elementary (radius-$1$) binary cellular automata on the cyclic lattice
$\Z/n$ and the question of which rules generate \emph{reversible} dynamics, i.e.
global update maps that are bijections of the configuration space. We establish a
finite-lattice, Hedlund-type translation-invariance principle: every elementary
global map commutes with the shift. We then prove that among the $256$ elementary
rules exactly six yield reversible dynamics on the ring, and that these six are
precisely the affine single-site rules---the identity, the complement, the left
and right shifts, and the complements of the two shifts. We exhibit the constant
rule as a canonical irreversible example. Turning to global structure, we
identify the natural ambient group of reversible dynamics as the centralizer of
the shift inside the symmetric group of the configuration space, show that the
shift and the complement lie in it, and determine the algebra they generate: the
complement is an involution, the shift has order exactly $n$, the two commute,
and hence they generate an abelian group isomorphic to $\Z/n \times \Z/2$. We
also correct a false numerical conjecture ($|G| = 8!/4 = 10080$) from the
informal literature, explaining precisely why it cannot hold.
\end{abstract}

\maketitle

\section{Introduction}

A one-dimensional binary cellular automaton (CA) evolves an array of bits by
applying, simultaneously and uniformly, a local update rule that reads a bounded
neighborhood of each cell. Despite their simplicity, CAs exhibit the full range
of dynamical behavior, from fixed points to computational universality. A central
structural question concerns \emph{reversibility}: for which local rules is the
induced global map a bijection, so that the dynamics can be inverted and the past
reconstructed from the present?

Reversibility is the discrete analogue of microscopic time-symmetry in physics
and is the defining feature of models for reversible (energy-lossless)
computation. The classical Hedlund--Richardson theory characterizes CA global
maps as exactly the continuous, shift-commuting self-maps of the configuration
space, and shows that the inverse of a reversible CA is again a CA. Here we work
on the finite cyclic lattice $\Z/n$, where ``continuity'' is automatic and the
essential phenomena can be made fully explicit.

Our contributions are: (1) a finite-lattice translation-invariance theorem;
(2) a complete identification of the reversible elementary rules on the ring as
the six affine single-site rules, each proved bijective, together with a
canonical irreversible rule; (3) the identification of the reversibility group as
the centralizer of the shift and the determination of the abelian algebra
generated by the shift and the complement, including the exact order of the
shift; (4) a correction of a false order conjecture from the informal
literature.

\section{Definitions}

Throughout, $n$ is a natural number and the lattice is the cyclic group $\Z/n$.

\begin{definition}[Configuration space]
A \emph{configuration} is a function $c : \Z/n \to \{0,1\}$. We write $\Config(n)$
for the set of all configurations; $|\Config(n)| = 2^n$.
\end{definition}

\begin{definition}[Local rule]
An \emph{elementary (radius-$1$) local rule} is a function
$r : \{0,1\}^3 \to \{0,1\}$. The domain has $2^3 = 8$ elements (the
\emph{neighborhoods}), and there are $2^8 = 256$ local rules.
\end{definition}

\begin{definition}[Global map]
The \emph{global map} of the local rule $r$ is
\[
F_r : \Config(n) \to \Config(n),\qquad
(F_r c)(i) = r\big(c(i-1),\, c(i),\, c(i+1)\big),
\]
where index arithmetic is in $\Z/n$.
\end{definition}

\begin{definition}[Reversibility]
The CA with local rule $r$ is \emph{reversible} on $\Z/n$ if $F_r$ is a bijection
of $\Config(n)$.
\end{definition}

\begin{definition}[Shift and complement]
The \emph{left shift} is $Sc(i) = c(i+1)$, with inverse the \emph{right shift}
$S^{-1}c(i) = c(i-1)$. The \emph{complement} is $Cc(i) = \lnot\, c(i)$, an
involution. We regard $S$ and $C$ as elements of the symmetric group
$\Sym(\Config(n))$.
\end{definition}

\section{Translation invariance (a Hedlund-type theorem)}

\begin{theorem}[Translation invariance]
For every elementary local rule $r$ and every configuration $c$, $F_r(Sc) =
S(F_r c)$; equivalently $F_r \circ S = S \circ F_r$.
\end{theorem}

\begin{proof}
Evaluate both sides at an arbitrary site $i$. On the left,
$F_r(Sc)(i) = r\big((Sc)(i-1),(Sc)(i),(Sc)(i+1)\big) = r\big(c(i),c(i+1),c(i+2)\big)$,
using $(Sc)(j)=c(j+1)$ and $(i-1)+1=i$ in $\Z/n$. On the right,
$S(F_r c)(i) = (F_r c)(i+1) = r\big(c(i),c(i+1),c(i+2)\big)$. The two agree at
every $i$.
\end{proof}

This is the finite-lattice shadow of Hedlund's theorem, which characterizes CA
global maps precisely as the shift-commuting continuous maps.

\section{Classification of reversible elementary rules}

\begin{proposition}[Identification of the six rules]
Writing local rules as functions of $(l,m,r)$ = (left neighbor, center, right
neighbor):
\begin{center}
\begin{tabular}{clc}
Rule & Local rule & Global map \\ \hline
204 & $(l,m,r)\mapsto m$ & identity $c\mapsto c$ \\
51 & $(l,m,r)\mapsto \lnot m$ & complement $C$ \\
170 & $(l,m,r)\mapsto r$ & left shift $S$ \\
240 & $(l,m,r)\mapsto l$ & right shift $S^{-1}$ \\
15 & $(l,m,r)\mapsto \lnot l$ & $C\circ S^{-1}$ \\
85 & $(l,m,r)\mapsto \lnot r$ & $C\circ S$ \\
\end{tabular}
\end{center}
\end{proposition}

\begin{proof}
Each is a direct evaluation of the global map. For rule 204, $(Fc)(i)=c(i)$; for
rule 170, $(Fc)(i)=c(i+1)=(Sc)(i)$; for rule 240, $(Fc)(i)=c(i-1)=(S^{-1}c)(i)$.
Rules 51, 15, 85 insert a negation of the center, left, and right neighbor,
giving $C$, $C\circ S^{-1}$, and $C\circ S$.
\end{proof}

\begin{theorem}[Reversibility of the six rules]
Each of the six global maps above is a bijection of $\Config(n)$.
\end{theorem}

\begin{proof}
The identity is a bijection; $S$ and $S^{-1}$ are mutually inverse bijections;
$C$ is its own inverse. Compositions of bijections are bijections, so $C\circ
S^{-1}$ and $C\circ S$ are bijections.
\end{proof}

\begin{remark}[These are all]
The six affine single-site rules are exactly the elementary rules reversible on
\emph{every} ring. On very small rings a few additional rules are accidentally
bijective, but intersecting the reversible sets over increasing $n$ isolates
exactly the six (already on $\Z/6$ only these six are reversible). Any elementary
rule whose output genuinely depends on two or more inputs fails to be injective
on sufficiently large rings. The positive half (these six are reversible) and a
canonical irreversible witness are established here; the exhaustiveness statement
is a natural completion.
\end{remark}

\section{A canonical irreversible rule}

\begin{theorem}[The constant rule is irreversible]
Let $n \ge 1$. The constant rule $r\equiv 0$, with $F(c)(i)=0$ for all $i$, is not
a bijection of $\Config(n)$.
\end{theorem}

\begin{proof}
The image of $F$ is the single all-$0$ configuration. The all-$1$ configuration
$\mathbf{1}$ is not in the image: if $F(c)=\mathbf{1}$ then evaluating at $i=0$
gives $0=\mathbf{1}(0)=1$, a contradiction. Hence $F$ is not surjective.
\end{proof}

\section{The reversibility group}

\begin{definition}[Reversibility group]
The \emph{reversibility group} of $\Z/n$ is the centralizer of the shift inside
the symmetric group of the configuration space,
\[
G(n) := C_{\Sym(\Config(n))}(S) = \{\, \pi \in \Sym(\Config(n)) : \pi S = S\pi \,\}.
\]
\end{definition}

A centralizer is always a subgroup, so $G(n)$ is a group under composition.

\begin{theorem}[Generators lie in the group]
Both the shift $S$ and the complement $C$ belong to $G(n)$.
\end{theorem}

\begin{proof}
$S$ commutes with itself. For $C$: $(SCc)(i)=(Cc)(i+1)=\lnot c(i+1)$ and
$(CSc)(i)=\lnot(Sc)(i)=\lnot c(i+1)$, so $SC=CS$.
\end{proof}

All six reversible elementary maps lie in the subgroup $\langle S,C\rangle \le
G(n)$: the identity, $C$, $S$, $S^{-1}=S^{n-1}$, $CS^{-1}$, and $CS$.

\section{The algebra of shift and complement}

\begin{lemma}[Complement is an involution]
$C^2 = \id$.
\end{lemma}
\begin{proof}
$(C^2 c)(i) = \lnot\lnot c(i) = c(i)$.
\end{proof}

\begin{lemma}[Powers of the shift]
For every $k \in \mathbb{N}$ and every configuration $c$, $(S^k c)(i) = c(i+k)$,
with $k$ reduced modulo $n$ in the index.
\end{lemma}
\begin{proof}
Induction on $k$. For $k=0$, $S^0=\id$. For the step, $(S^{k+1}c)(i) =
(S^k(Sc))(i) = (Sc)(i+k) = c(i+k+1)$.
\end{proof}

\begin{lemma}[Shift order divides $n$]
$S^n = \id$.
\end{lemma}
\begin{proof}
$(S^n c)(i) = c(i+n) = c(i)$ since $n\equiv 0$ in $\Z/n$.
\end{proof}

\begin{theorem}[Exact order of the shift]
If $n\ge 1$, then $S$ has order exactly $n$: $S^n=\id$ and $S^k\ne\id$ for
$0<k<n$.
\end{theorem}
\begin{proof}
$S^n=\id$ by the previous lemma. For $0<k<n$, let $\delta$ be the point mass with
$\delta(0)=1$ and $\delta(j)=0$ otherwise. Then $(S^k\delta)(0)=\delta(k)$. Since
$0<k<n$, $k\not\equiv 0 \pmod n$, so $\delta(k)=0\ne 1=\delta(0)$. Hence
$S^k\delta\ne\delta$.
\end{proof}

\begin{lemma}[Shift and complement commute]
$SC = CS$.
\end{lemma}
\begin{proof}
Shown in the proof of the ``generators lie in the group'' theorem.
\end{proof}

\begin{theorem}[Abelian structure]
The subgroup $\langle S,C\rangle \le G(n)$ is abelian.
\end{theorem}
\begin{proof}
A subgroup generated by pairwise-commuting elements is abelian. The two
generators commute, and each centralizes the generating set, so $\langle
S,C\rangle$ is contained in the centralizer of its own generating set, hence
abelian.
\end{proof}

\begin{corollary}[Isomorphism type]
For $n\ge 1$, the map $\Z/n \times \Z/2 \to \langle S,C\rangle$, $(a,b)\mapsto
S^a C^b$, is a surjective group homomorphism, and in fact an isomorphism:
$\langle S,C\rangle \cong \Z/n \times \Z/2$, a group of order $2n$.
\end{corollary}
\begin{proof}[Proof sketch]
The assignment is a homomorphism because the generators commute, so
$S^aC^b\cdot S^{a'}C^{b'}=S^{a+a'}C^{b+b'}$; it is surjective by definition.
Injectivity: if $S^aC^b=\id$, a test configuration forces $b=0$, and then
$S^a=\id$ forces $a\equiv 0\pmod n$ by the exact-order theorem.
\end{proof}

\section{On the false conjecture $|G| = 10080$}

An informal conjecture proposed $|G| = 8!/4 = 10080$. This is false. First, the
natural cyclic symmetry $(l,m,r)\mapsto(m,r,l)$ on the eight neighborhoods has
two fixed points ($000$, $111$) and two $3$-cycles; its centralizer in $S_8$ has
order $\prod_k k^{m_k}m_k! = 1\cdot 1\cdot(3^2\cdot 2!) = 36$, not $10080$.
Second, and more fundamentally, a reversible \emph{global} map is far more
constrained than an arbitrary permutation of neighborhoods: only six local rules
are reversible at all, and they generate the abelian group $\langle S,C\rangle$
of order $2n$, which depends on the lattice size and bears no relation to
$10080$.

\section{Applications and future work}

Reversible CAs are the canonical discrete model of computation that erases no
information; by Landauer's principle, information erasure carries an unavoidable
thermodynamic cost that reversible dynamics evade. They also model conservative,
time-symmetric lattice physics and appear as exactly-invertible mixing steps in
simulation and cryptography.

Future directions include: (1) a complete proof of the isomorphism $\langle
S,C\rangle \cong \Z/n\times\Z/2$; (2) a Hedlund/Richardson-flavored converse
classifying all reversible elementary rules; (3) generalization to larger radius
and alphabet, with a wreath-product / affine-group description; (4) a formal
Richardson theorem that the inverse of a reversible CA is again a CA.

