from itertools import product
from typing import Callable, List, Tuple

Config = Tuple[int, ...]
LocalRule = Callable[[int, int, int], int]

def wolfram(number: int) -> LocalRule:
    """Local rule (l, m, r) -> bit for a Wolfram rule number 0..255."""
    def rule(l: int, m: int, r: int) -> int:
        return (number >> ((l << 2) | (m << 1) | r)) & 1
    return rule

def global_map(rule: LocalRule, c: Config) -> Config:
    n = len(c)
    return tuple(rule(c[(i - 1) % n], c[i], c[(i + 1) % n]) for i in range(n))

def is_bijective(rule: LocalRule, n: int) -> bool:
    cfgs = [tuple(b) for b in product((0, 1), repeat=n)]
    return len({global_map(rule, c) for c in cfgs}) == len(cfgs)

def rules_reversible_on_all_rings(max_n: int = 8) -> List[int]:
    """Rules bijective on every ring Z/n for 2 <= n <= max_n."""
    survivors = set(range(256))
    for n in range(2, max_n + 1):
        survivors &= {r for r in range(256) if is_bijective(wolfram(r), n)}
    return sorted(survivors)

if __name__ == "__main__":
    print("Reversible on all rings:", rules_reversible_on_all_rings())
    # -> [15, 51, 85, 170, 204, 240]

from itertools import product
from typing import Dict, List, Tuple

Config = Tuple[int, ...]

def shift(c: Config) -> Config:
    n = len(c)
    return tuple(c[(i + 1) % n] for i in range(n))

def complement(c: Config) -> Config:
    return tuple(1 - b for b in c)

def apply_word(word: List[str], c: Config) -> Config:
    for g in reversed(word):
        c = shift(c) if g == "S" else complement(c)
    return c

def perm_of(word: List[str], n: int) -> Tuple[Config, ...]:
    return tuple(apply_word(word, c) for c in
                 (tuple(b) for b in product((0, 1), repeat=n)))

def shift_complement_group(n: int) -> Dict[Tuple[int, int], Tuple[Config, ...]]:
    """Enumerate S^a C^b as permutations; keys are (a, b)."""
    return {(a, b): perm_of(["S"] * a + (["C"] if b else []), n)
            for a in range(n) for b in range(2)}

if __name__ == "__main__":
    for n in (3, 4, 5, 6):
        g = shift_complement_group(n)
        order = len(set(g.values()))
        print(f"n={n}: |<S,C>| = {order} (expected 2n = {2 * n}) "
              f"-> Z/{n} x Z/2")

