def wolfram(number: int) -> LocalRule:
    def rule(l: int, m: int, r: int) -> int:
        return (number >> ((l << 2) | (m << 1) | r)) & 1
    return rule

def global_map(rule: LocalRule, c: Config) -> Config:
    n = len(c)
    return tuple(rule(c[(i - 1) % n], c[i], c[(i + 1) % n]) for i in range(n))

def trajectory(rule: LocalRule, c: Config, steps: int) -> List[Config]:
    """Forward orbit of a configuration under a rule."""
    out = [c]
    for _ in range(steps):
        c = global_map(rule, c)
        out.append(c)
    return out

def cycle_length(rule: LocalRule, c: Config) -> int:
    """Length of the eventual cycle reached from c (finite state space)."""
    seen = {}
    t = 0
    while c not in seen:
        seen[c] = t
        c = global_map(rule, c)
        t += 1
    return t - seen[c]

if __name__ == "__main__":
    # Reversible rule 170 (left shift) has all orbits pure cycles.
    n = 6
    c0 = (1, 0, 0, 0, 0, 0)
    print("Rule 170 orbit of point mass on Z/6:")
    for row in trajectory(wolfram(170), c0, 6):
        print("  " + "".join(str(b) for b in row))
    print("Cycle length =", cycle_length(wolfram(170), c0))  # -> 6

