"""Cayley-table heatmap of the group <S, C> ~ Z/n x Z/2."""
import matplotlib.pyplot as plt
import numpy as np
from itertools import product

def shift(c):
    n = len(c); return tuple(c[(i+1) % n] for i in range(n))
def complement(c):
    return tuple(1 - b for b in c)
def apply_word(word, c):
    for g in reversed(word):
        c = shift(c) if g == "S" else complement(c)
    return c

n = 4
cfgs = [tuple(b) for b in product((0, 1), repeat=n)]
elems = [("S" * a + ("C" if b else ""), (a, b))
         for a in range(n) for b in range(2)]
perms = {lbl: tuple(apply_word(list(w), c) for c in cfgs) for w, lbl in elems}
labels = [lbl for _, lbl in elems]
index = {perms[l]: i for i, l in enumerate(labels)}

def compose(p, q):  # p after q
    pos = {c: p[i] for i, c in enumerate(cfgs)}
    return tuple(pos[x] for x in q)

table = np.zeros((len(labels), len(labels)), dtype=int)
for i, a in enumerate(labels):
    for j, b in enumerate(labels):
        table[i, j] = index[compose(perms[a], perms[b])]
plt.figure(figsize=(7, 6))
plt.imshow(table, cmap="viridis")
plt.title(f"Cayley table of <S, C> on Z/{n}  (order {2*n}, abelian)")
plt.colorbar(label="product index")
plt.xticks(range(len(labels)), [str(l) for l in labels], rotation=90)
plt.yticks(range(len(labels)), [str(l) for l in labels])
plt.tight_layout(); plt.savefig("cayley_table.png", dpi=150)
